from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def read_public(path: str) -> str:
    """Return the text of `path` resolved inside NOTES_DIR, or "".

    Paths that resolve outside NOTES_DIR (via "..", absolute paths, or
    any other escape) return "". Missing, unreadable, or non-file
    targets also return "".
    """
    try:
        base = NOTES_DIR.resolve()
        target = (base / path).resolve()
        if not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


@pytest.fixture
def notes_cwd(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    return tmp_path


def test_reads_file_inside_notes(notes_cwd: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_nested_file(notes_cwd: Path) -> None:
    assert read_public("sub/b.txt") == "nested"


def test_inner_dotdot_that_stays_inside_is_allowed(notes_cwd: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"


def test_missing_file_gives_empty_string(notes_cwd: Path) -> None:
    assert read_public("nope.txt") == ""


def test_directory_gives_empty_string(notes_cwd: Path) -> None:
    assert read_public("sub") == ""


def test_dotdot_escape_is_blocked(notes_cwd: Path) -> None:
    assert read_public("../secret.txt") == ""


def test_bare_dotdot_is_blocked(notes_cwd: Path) -> None:
    assert read_public("..") == ""


def test_deep_escape_after_inner_segment_is_blocked(notes_cwd: Path) -> None:
    assert read_public("sub/../../secret.txt") == ""


def test_absolute_path_is_blocked(notes_cwd: Path) -> None:
    absolute = str((notes_cwd / "secret.txt").resolve())
    assert read_public(absolute) == ""
